#!/usr/bin/env python3
"""Validate the structural invariants of a core-strategy log."""

from __future__ import annotations

import re
import sys
from pathlib import Path

COVERAGE_LINE = "分析覆盖：RAG/RETRIEVAL=已检查；PREPARED-KNOWLEDGE=已检查；CODE-REUSE=已检查；PROMPT-ORCHESTRATION=已检查；MODEL-ROUTING=已检查；TOOLS/EXECUTION=已检查；ITERATION/EVALUATION=已检查；STATE/PERSISTENCE=已检查"
HEADING = re.compile(r"^STRATEGY-(\d{3}) \[([^\]]+)\] .+")
VALID_CATEGORIES = {"RAG/RETRIEVAL", "PREPARED-KNOWLEDGE", "CODE-REUSE", "PROMPT-ORCHESTRATION", "MODEL-ROUTING", "TOOLS/EXECUTION", "ITERATION/EVALUATION", "STATE/PERSISTENCE"}
REQUIRED_DIMENSIONS = ("状态", "作用", "输入/知识源", "选择/检索", "生成/使用", "输出")
REQUIRED_PARTS = ("具体说明", "代码/文档定位", "详细解释")
GENERIC_SUMMARIES = {"生成页面", "组件库", "关键词选择", "模型生成", "输出代码", "生成代码", "无", "未知"}


def part_value(section: list[str], part: str) -> str | None:
    prefix = f"    {REQUIRED_PARTS.index(part) + 1}. {part}："
    return next((line.removeprefix(prefix).strip() for line in section if line.startswith(prefix)), None)


def dimension_section(block: list[str], dimension: str) -> list[str] | None:
    marker = f"  - {dimension}："
    try:
        start = block.index(marker)
    except ValueError:
        return None
    end = len(block)
    for index in range(start + 1, len(block)):
        if any(block[index] == f"  - {candidate}：" for candidate in REQUIRED_DIMENSIONS):
            end = index
            break
    return block[start + 1:end]


def validate(path: Path) -> list[str]:
    if not path.is_file():
        return [f"report does not exist: {path}"]
    try:
        text = path.read_bytes().decode("utf-8")
    except UnicodeDecodeError as error:
        return [f"report is not valid UTF-8: byte {error.start}: {error.reason}"]
    errors = []
    if "\ufffd" in text:
        errors.append("report contains Unicode replacement characters")
    if any("\ue000" <= character <= "\uf8ff" for character in text):
        errors.append("report contains private-use characters")
    if re.search(r"\?{3,}", text):
        errors.append("report contains three or more consecutive question marks")
    lines = text.splitlines()
    for required in ("[核心结论]", "[策略清单]", "[未发现或未解决]", COVERAGE_LINE):
        if required not in lines:
            errors.append(f"missing required line: {required}")
    if not lines or lines[-1] != "分析完成":
        errors.append("last non-empty line must be 分析完成")
    headings = [(index, match) for index, line in enumerate(lines) if (match := HEADING.match(line))]
    numbers = [int(match.group(1)) for _, match in headings]
    if numbers != list(range(1, len(numbers) + 1)):
        errors.append("strategy numbering must be consecutive from 001")
    for position, (start, match) in enumerate(headings):
        if match.group(2) not in VALID_CATEGORIES:
            errors.append(f"STRATEGY-{match.group(1)} has unknown category: {match.group(2)}")
        end = headings[position + 1][0] if position + 1 < len(headings) else len(lines)
        block = lines[start + 1:end]
        for dimension in REQUIRED_DIMENSIONS:
            section = dimension_section(block, dimension)
            if section is None:
                errors.append(f"STRATEGY-{match.group(1)} missing dimension: {dimension}")
                continue
            values = {}
            for part in REQUIRED_PARTS:
                value = part_value(section, part)
                values[part] = value
                if not value:
                    errors.append(f"STRATEGY-{match.group(1)} {dimension} missing part: {part}")
            summary = values.get("具体说明")
            if summary:
                if summary in GENERIC_SUMMARIES or len(summary) < 10:
                    errors.append(f"STRATEGY-{match.group(1)} {dimension} 具体说明 is too terse or generic")
                if dimension == "状态" and not re.match(r"^(confirmed|inferred|unresolved)\b", summary):
                    errors.append(f"STRATEGY-{match.group(1)} 状态 must begin with confirmed, inferred, or unresolved")
            location = values.get("代码/文档定位")
            if location and not re.search(r"[^；;，,\s]+:\d+", location):
                errors.append(f"STRATEGY-{match.group(1)} {dimension} location must contain path:line")
            explanation = values.get("详细解释")
            if explanation and len(explanation) < 30:
                errors.append(f"STRATEGY-{match.group(1)} {dimension} 详细解释 is too short")
    if "RAG" not in text or "代码复用" not in text:
        errors.append("report must explicitly state RAG and code-reuse conclusions")
    return errors


def main() -> int:
    if len(sys.argv) != 2:
        print("usage: validate_report.py <result.log>", file=sys.stderr)
        return 2
    errors = validate(Path(sys.argv[1]))
    if errors:
        for error in errors:
            print(f"ERROR: {error}", file=sys.stderr)
        return 1
    print("report structure is valid")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

import datetime
import re

__all__ = ["YAMLError", "load_yaml", "load_requirements", "plan", "mask"]


class YAMLError(ValueError):
    pass


_KEY = re.compile(r"""^(?P<key>[^\s'"\[\]{},#&*!|>%@`-](?:[^:\n]|:(?=\S))*?|-(?=\S)(?:[^:\n]|:(?=\S))*?)"""
                  r"""[ \t]*:(?:[ \t]+(?P<rest>.*))?$""")
_BLOCK_HEADER = re.compile(r"^([|>])([+-]?)([1-9]?)([+-]?)[ \t]*(?:#.*)?$")
_NULL = {"", "~", "null", "Null", "NULL"}
_BOOL = {**{w: True for w in ("yes", "Yes", "YES", "true", "True", "TRUE", "on", "On", "ON")},
         **{w: False for w in ("no", "No", "NO", "false", "False", "FALSE", "off", "Off", "OFF")}}
_INT = re.compile(r"^[-+]?(?:0|[1-9][0-9_]*)$")
_INT_BASE = re.compile(r"^([-+]?)0(b[01_]+|x[0-9a-fA-F_]+|[0-7_]+)$")
_FLOAT = re.compile(r"^(?:[-+]?[0-9][0-9_]*\.[0-9_]*(?:[eE][-+][0-9]+)?|\.[0-9][0-9_]*(?:[eE][-+][0-9]+)?)$")
_DATE = re.compile(r"^([0-9]{4})-([0-9]{2})-([0-9]{2})$")
_ESCAPES = {"0": "\0", "a": "\a", "b": "\b", "t": "\t", "\t": "\t", "n": "\n", "v": "\v", "f": "\f",
            "r": "\r", "e": "\x1b", " ": " ", '"': '"', "/": "/", "\\": "\\", "N": "\x85", "_": "\xa0",
            "L": " ", "P": " "}


def _resolve(text):
    if text in _NULL:
        return None
    if text in _BOOL:
        return _BOOL[text]
    if _INT.match(text):
        return int(text.replace("_", ""))
    match = _INT_BASE.match(text)
    if match:
        body = match.group(2).replace("_", "")
        base, digits = (2, body[1:]) if body[0] == "b" else (16, body[1:]) if body[0] == "x" else (8, body)
        return (-1 if match.group(1) == "-" else 1) * int(digits or "0", base)
    if _FLOAT.match(text):
        return float(text.replace("_", ""))
    if re.match(r"^[-+]?\.(?:inf|Inf|INF)$", text):
        return float("-inf") if text.startswith("-") else float("inf")
    if re.match(r"^\.(?:nan|NaN|NAN)$", text):
        return float("nan")
    match = _DATE.match(text)
    if match:
        try:
            return datetime.date(*(int(part) for part in match.groups()))
        except ValueError:
            return text
    return text


def _quote_end(text, start, quote):
    i = start
    while i < len(text):
        if quote == '"' and text[i] == "\\":
            i += 2
            continue
        if text[i] == quote:
            if quote == "'" and text[i + 1:i + 2] == "'":
                i += 2
                continue
            return i
        i += 1
    return None


def _unescape(body):
    out, i = [], 0
    while i < len(body):
        if body[i] != "\\":
            out.append(body[i])
            i += 1
            continue
        code = body[i + 1:i + 2]
        if code in _ESCAPES:
            out.append(_ESCAPES[code])
            i += 2
        elif code in ("x", "u", "U"):
            width = {"x": 2, "u": 4, "U": 8}[code]
            try:
                out.append(chr(int(body[i + 2:i + 2 + width], 16)))
            except ValueError:
                raise YAMLError(f"bad escape \\{code}{body[i + 2:i + 2 + width]}") from None
            i += 2 + width
        else:
            raise YAMLError(f"unknown escape \\{code}")
    return "".join(out)


def _unquote(body, quote):
    return body.replace("''", "'") if quote == "'" else _unescape(body)


def _fold(lines):
    out, empties = lines[0], 0
    for index in range(1, len(lines)):
        line = lines[index]
        if line == "" and index < len(lines) - 1:
            empties += 1
            continue
        out += "\n" * empties if empties else " "
        out += line
        empties = 0
    return out


def _strip_comment(text):
    match = re.search(r"[ \t]#", text)
    return (text[:match.start()] if match else text).strip()


class _Incomplete(Exception):
    pass


def _skip_space(text, i):
    while i < len(text) and text[i] in " \t":
        i += 1
    return i


def _flow(text, i, key=False):
    i = _skip_space(text, i)
    if i >= len(text):
        raise _Incomplete
    head = text[i]
    if head in "[{":
        close, items, mapping = ("]" if head == "[" else "}"), [], {}
        i += 1
        while True:
            i = _skip_space(text, i)
            if i >= len(text):
                raise _Incomplete
            if text[i] == close:
                return (items if head == "[" else mapping), i + 1
            if head == "[":
                value, i = _flow(text, i)
                items.append(value)
            else:
                name, i = _flow(text, i, key=True)
                i = _skip_space(text, i)
                value = None
                if i < len(text) and text[i] == ":":
                    value, i = _flow(text, i + 1)
                mapping[name] = value
            i = _skip_space(text, i)
            if i >= len(text):
                raise _Incomplete
            if text[i] == ",":
                i += 1
            elif text[i] != close:
                raise YAMLError(f"unexpected {text[i]!r} in flow collection")
    if head in "'\"":
        end = _quote_end(text, i + 1, head)
        if end is None:
            raise _Incomplete
        return _unquote(text[i + 1:end], head), end + 1
    j = i
    while j < len(text) and text[j] not in ",]}" and not (text[j] == "#" and text[j - 1] in " \t"):
        if text[j] == ":" and (j + 1 == len(text) or text[j + 1] in " \t,]}"):
            break
        j += 1
    raw = text[i:j].strip()
    return (raw if key else _resolve(raw)), j


class _Parser:
    def __init__(self, text):
        self.lines = text.lstrip("﻿").replace("\r\n", "\n").replace("\r", "\n").split("\n")

    @staticmethod
    def indent(line):
        return len(line) - len(line.lstrip(" "))

    def skip(self, i):
        while i < len(self.lines):
            stripped = self.lines[i].strip()
            marker = self.lines[i][:3] in ("---", "...") and stripped in ("---", "...")
            if stripped and not stripped.startswith("#") and not marker:
                return i
            i += 1
        return i

    def document(self):
        i = self.skip(0)
        if i >= len(self.lines):
            return None
        value, i = self.node(i, self.indent(self.lines[i]), -1)
        i = self.skip(i)
        if i < len(self.lines):
            raise YAMLError(f"line {i + 1}: unexpected content {self.lines[i].strip()[:60]!r}")
        return value

    def node(self, i, indent, parent):
        content = self.lines[i][indent:]
        if content == "-" or content.startswith("- "):
            return self.sequence(i, indent)
        if self.key(content) is not None:
            return self.mapping(i, indent)
        return self.scalar(i, content, parent)

    def key(self, content):
        if content[:1] in ("'", '"'):
            end = _quote_end(content, 1, content[0])
            if end is None or not re.match(r":(?:[ \t]|$)", content[end + 1:]):
                return None
            return _unquote(content[1:end], content[0]), content[end + 2:].strip()
        match = _KEY.match(content)
        if not match:
            return None
        return match.group("key"), (match.group("rest") or "").strip()

    def mapping(self, i, indent):
        result = {}
        while True:
            i = self.skip(i)
            if i >= len(self.lines):
                return result, i
            line = self.lines[i]
            level = self.indent(line)
            if level < indent:
                return result, i
            if level > indent:
                raise YAMLError(f"line {i + 1}: unexpected indentation")
            pair = self.key(line[indent:])
            if pair is None:
                return result, i
            name, rest = pair
            result[name], i = self.value(i, indent, rest)

    def value(self, i, indent, rest):
        if not rest or rest.startswith("#"):
            j = self.skip(i + 1)
            if j < len(self.lines):
                line = self.lines[j]
                level = self.indent(line)
                if level > indent:
                    return self.node(j, level, indent)
                if level == indent and (line[level:] == "-" or line[level:].startswith("- ")):
                    return self.sequence(j, level)
            return None, i + 1
        return self.scalar(i, rest, indent)

    def sequence(self, i, indent):
        result = []
        while True:
            i = self.skip(i)
            if i >= len(self.lines):
                return result, i
            line = self.lines[i]
            level = self.indent(line)
            if level < indent:
                return result, i
            if level > indent:
                raise YAMLError(f"line {i + 1}: unexpected indentation")
            content = line[indent:]
            if not (content == "-" or content.startswith("- ")):
                return result, i
            after = content[1:]

