    1: 'use strict';
    2: // Backend scaffold. Mechanics it satisfies: `npm run start` listens on PORT, serves ../frontend/dist
    3: // with `/` -> index.html, answers GET /api/health with exactly {"code":200,"message":"Backend Ready"}
    4: // only once the seed is in place, keeps the shared records in memory, never lets a handler kill the process.
    5: // Add domain routes inside `api()`; keep everything else.
    6: const http = require('node:http');
    7: const fs = require('node:fs');
    8: const path = require('node:path');
    9: const vm = require('node:vm');
   10: 
   11: process.on('uncaughtException', (e) => console.error('uncaught', e));
   12: process.on('unhandledRejection', (e) => console.error('unhandled', e));
   13: 
   14: const DIST = path.resolve(__dirname, '..', 'frontend', 'dist');
   15: const TYPES = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8',
   16:   '.css': 'text/css; charset=utf-8', '.json': 'application/json; charset=utf-8', '.svg': 'image/svg+xml',
   17:   '.png': 'image/png', '.jpg': 'image/jpeg', '.ico': 'image/x-icon' };
   18: 
   19: // The shared records every browser session reads (GET /api/state) and writes (PUT /api/state). A fresh
   20: // process starts from the frontend's seed.js; `session` and `ui` belong to each browser, never here.
   21: function loadSeed() {
   22:   for (const file of [path.join(DIST, 'seed.js'), path.resolve(__dirname, '..', 'frontend', 'public', 'seed.js')]) {
   23:     try {
   24:       const sandbox = { window: {} };
   25:       vm.runInNewContext(fs.readFileSync(file, 'utf8'), sandbox, { timeout: 2000 });
   26:       const seed = sandbox.window.SEED;
   27:       if (seed && typeof seed === 'object' && !Array.isArray(seed)) {
   28:         const shared = JSON.parse(JSON.stringify(seed));
   29:         delete shared.session; delete shared.ui;
   30:         return shared;
   31:       }
   32:     } catch (e) { console.error('seed', file, e.message); }
   33:   }
   34:   return null;
   35: }
   36: let STATE = loadSeed();
   37: 
   38: function json(res, status, body) {
   39:   res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
   40:   res.end(JSON.stringify(body));
   41: }
   42: 
   43: function readBody(req) {
   44:   return new Promise((resolve, reject) => {
   45:     const chunks = [];
   46:     req.on('data', (c) => { chunks.push(c); if (chunks.reduce((n, b) => n + b.length, 0) > 8e6) req.destroy(); });
   47:     req.on('end', () => { try { resolve(chunks.length ? JSON.parse(Buffer.concat(chunks).toString('utf8')) : null); } catch (e) { reject(e); } });
   48:     req.on('error', reject);
   49:   });
   50: }
   51: 
   52: async function api(req, res, url) {
   53:   if (url.pathname === '/api/health') return json(res, 200, { code: 200, message: 'Backend Ready' });
   54:   if (url.pathname === '/api/state') {
   55:     if (req.method === 'GET') return json(res, 200, STATE || {});
   56:     if (req.method === 'PUT') {
   57:       const body = await readBody(req);
   58:       if (!body || typeof body !== 'object' || Array.isArray(body)) return json(res, 400, { error: 'state must be an object' });
   59:       STATE = body;
   60:       return json(res, 200, { ok: true });
   61:     }
   62:   }
   63:   // Domain routes go here, e.g. if (url.pathname === '/api/items' && req.method === 'GET') ...
   64:   return json(res, 404, { error: 'not found' });
   65: }
   66: 
   67: function serveStatic(res, pathname) {
   68:   let file = path.normalize(path.join(DIST, decodeURIComponent(pathname)));
   69:   if (!file.startsWith(DIST)) return json(res, 403, { error: 'forbidden' });
   70:   if (pathname === '/' || !fs.existsSync(file) || fs.statSync(file).isDirectory()) file = path.join(DIST, 'index.html');
   71:   const type = TYPES[path.extname(file).toLowerCase()] || 'application/octet-stream';
   72:   res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-store' });
   73:   fs.createReadStream(file).on('error', () => { res.end(); }).pipe(res);
   74: }
   75: 
   76: const server = http.createServer(async (req, res) => {
   77:   try {
   78:     const url = new URL(req.url, 'http://localhost');
   79:     if (url.pathname.startsWith('/api/')) return await api(req, res, url);
   80:     return serveStatic(res, url.pathname);
   81:   } catch (e) {
   82:     console.error('handler', e);
   83:     if (!res.headersSent) json(res, 500, { error: 'internal' }); else res.end();
   84:   }
   85: });
   86: server.listen(Number(process.env.PORT) || 3000, () => console.log('listening', server.address().port));

